def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                x, y = stack.pop()
                cells.add((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                        grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append((color, cells))

    # Find an L-shaped line, then recolor the object beneath its horizontal arm
    # whose columns overlap the arm.
    for line_color, line in components:
        r0 = min(r for r, c in line)
        r1 = max(r for r, c in line)
        c0 = min(c for r, c in line)
        c1 = max(c for r, c in line)
        height, width = r1-r0+1, c1-c0+1
        if height < 2 or width < 2 or len(line) != height + width - 1:
            continue

        found = False
        for hr in (r0, r1):
            for vc in (c0, c1):
                expected = ({(r, vc) for r in range(r0, r1+1)} |
                            {(hr, c) for c in range(c0, c1+1)})
                if line != expected:
                    continue
                # Choose the closest component below the horizontal segment
                # that has at least one cell within its column span.
                candidates = []
                for color, cells in components:
                    if color == line_color:
                        continue
                    overlap = [c for r, c in cells if c0 <= c <= c1 and r > hr]
                    if overlap:
                        top = min(r for r, c in cells if c in overlap and r > hr)
                        candidates.append((top - hr, color, cells))
                if candidates:
                    _, target_color, target = min(candidates, key=lambda x: x[0])
                    out = [row[:] for row in grid]
                    for r, c in target:
                        out[r][c] = line_color
                    return out
                found = True
        if found:
            continue

    return [row[:] for row in grid]
